-- AFA World Series 2026 — Men's D: division, 16 teams, venues, 35-game 3GG bracket.
-- GENERATED by scripts/worlds-2026-mens-d/build-sql.mjs from sheet.mjs. Do not hand-edit.
--
-- Needs supabase/migration-2026-11-08-tournament-venues.sql first (adds tournaments.venues).
-- NOT RUN. Run only with J.D.'s OK, against the live project, in the SQL editor
-- (one statement block; it is its own transaction).
--
-- What it writes (tournament 2026-afa-world-series, e87a664d-e165-41c0-9a41-deb86b0dfd2e):
--   tournaments  1 row updated  venues = Hunter Park + Pioneer Park (name, address, map link)
--   divisions    1 row inserted "Men's D" (mens, class D)
--   registrations 16 rows inserted, confirmed, no manager / roster (team-without-manager.sql)
--   brackets     1 row inserted (main, three_gg_hybrid, 16 teams)
--   games        35 rows inserted (round = sheet G#, slot 0), then Winner/Loser links
--
-- Idempotent: re-running changes nothing that already matches. It refuses
-- (raises, rolls back) if Men's D already has a scored game or games that
-- are not this sheet's G1–G35.
--
-- Times. The sheet's times are Mesquite wall clock (Pacific). The site
-- renders every game in America/Denver (lib/bracket/tree.js LEAGUE_TZ).
-- v_tz below is the zone the sheet's wall-clock times are stored in:
--   'America/Denver'       site shows the sheet's times (2 PM reads 2 PM);
--                          the .ics calendar export is 1 hour early in Mesquite.
--   'America/Los_Angeles'  true instants; the site would show 3 PM for a 2 PM game.
-- Default is 'America/Denver' so every screen matches the paper.

do $$
declare
  v_tz text := 'America/Denver';
  v_tournament uuid := 'e87a664d-e165-41c0-9a41-deb86b0dfd2e';
  v_class uuid;
  v_div uuid;
  v_teams text[] := array['Banana Slugs', 'Vice', 'Ragin Rhinos', 'Phat Kids', 'Los Homies', 'Cage Bombs', 'Glove Workz', 'Channel 4', 'Jaded', 'Fallen', 'SIS', 'Da Bumbs', 'Elite', '208 Mafia', '435 Outlaws', 'Castlewood'];
  v_bad int;
  v_n int;
begin
  if not exists (select 1 from public.tournaments where id = v_tournament and slug = '2026-afa-world-series') then
    raise exception 'AFA World Series tournament % not found', v_tournament;
  end if;

  select id into v_class from public.classes where name = 'D';
  if v_class is null then raise exception 'class D not found'; end if;

  -- 1. Venues (two parks, map links)
  update public.tournaments
     set venues = '[{"name":"Hunter Park","address":"500 E Mesquite Blvd, Mesquite, NV 89027","field_prefix":"Hunter","map_url":"https://www.google.com/maps/search/?api=1&query=Hunter%20Park%2C%20500%20E%20Mesquite%20Blvd%2C%20Mesquite%2C%20NV%2089027"},{"name":"Pioneer Park","address":"501 Hillside Drive, Mesquite, NV 89027","field_prefix":"Pioneer","map_url":"https://www.google.com/maps/search/?api=1&query=Pioneer%20Park%2C%20501%20Hillside%20Drive%2C%20Mesquite%2C%20NV%2089027"}]'::jsonb
   where id = v_tournament
     and venues is distinct from '[{"name":"Hunter Park","address":"500 E Mesquite Blvd, Mesquite, NV 89027","field_prefix":"Hunter","map_url":"https://www.google.com/maps/search/?api=1&query=Hunter%20Park%2C%20500%20E%20Mesquite%20Blvd%2C%20Mesquite%2C%20NV%2089027"},{"name":"Pioneer Park","address":"501 Hillside Drive, Mesquite, NV 89027","field_prefix":"Pioneer","map_url":"https://www.google.com/maps/search/?api=1&query=Pioneer%20Park%2C%20501%20Hillside%20Drive%2C%20Mesquite%2C%20NV%2089027"}]'::jsonb;

  -- 2. Division
  insert into public.divisions (
    tournament_id, name, display_name, gender, class_id, bracket_type,
    sort_order, day_date, day_label, min_teams, min_men, min_women
  )
  values (
    v_tournament, 'Men''s D', 'Men''s D', 'mens', v_class, 'double_elimination',
    0, date '2026-11-12', 'Thu–Fri, Nov 12–13', 6, 10, 0
  )
  on conflict (tournament_id, name) do nothing;

  select id into v_div from public.divisions where tournament_id = v_tournament and name = 'Men''s D';

  -- Refuse to touch a bracket someone has started scoring, or a different one.
  select count(*) into v_bad from public.games
   where division_id = v_div
     and (status = 'final' or bracket_group <> 'main' or slot <> 0 or round not between 1 and 35);
  if v_bad > 0 then
    raise exception 'Men''s D already has % scored or foreign game rows; not loading', v_bad;
  end if;

  -- 3. Teams: one live registration each, no manager, no roster.
  insert into public.registrations (
    tournament_id, division_id, team_name, class_id, manager_name, manager_email, status
  )
  select v_tournament, v_div, t, v_class, null, null, 'confirmed'
    from unnest(v_teams) as t
   where not exists (
     select 1 from public.registrations r
      where r.division_id = v_div and r.status <> 'withdrawn'
        and lower(btrim(r.team_name)) = lower(btrim(t))
   );
  get diagnostics v_n = row_count;
  raise notice 'registrations inserted: %', v_n;

  -- 4. Bracket metadata
  insert into public.brackets (division_id, bracket_group, format, team_count, bracket_size)
  values (v_div, 'main', 'three_gg_hybrid', 16, 16)
  on conflict (division_id, bracket_group) do update
    set format = excluded.format, team_count = excluded.team_count, bracket_size = excluded.bracket_size;

  -- 5. Games. round = the sheet's game number (paper G#), slot 0.
  create temp table _sheet (
    n int primary key, side text, t1 text, t2 text,
    s1 int, r1 text, s2 int, r2 text, at_local text, field text
  ) on commit drop;
  insert into _sheet values
    (1, 'winners', 'Banana Slugs', 'Vice', null, null, null, null, '2026-11-12 14:00', 'Hunter F1'),
    (2, 'winners', 'Ragin Rhinos', 'Phat Kids', null, null, null, null, '2026-11-12 14:00', 'Hunter F2'),
    (3, 'winners', 'Los Homies', 'Cage Bombs', null, null, null, null, '2026-11-12 14:00', 'Hunter F3'),
    (4, 'winners', 'Glove Workz', 'Channel 4', null, null, null, null, '2026-11-12 15:00', 'Hunter F1'),
    (5, 'winners', 'Jaded', 'Fallen', null, null, null, null, '2026-11-12 15:00', 'Hunter F2'),
    (6, 'winners', 'SIS', 'Da Bumbs', null, null, null, null, '2026-11-12 15:00', 'Hunter F3'),
    (7, 'winners', 'Elite', '208 Mafia', null, null, null, null, '2026-11-12 16:00', 'Hunter F1'),
    (8, 'winners', '435 Outlaws', 'Castlewood', null, null, null, null, '2026-11-12 16:00', 'Hunter F2'),
    (9, 'losers', null, null, 1, 'loser', 2, 'loser', '2026-11-12 16:00', 'Hunter F3'),
    (10, 'losers', null, null, 3, 'loser', 4, 'loser', '2026-11-12 17:00', 'Hunter F1'),
    (11, 'losers', null, null, 5, 'loser', 6, 'loser', '2026-11-12 17:00', 'Hunter F2'),
    (12, 'losers', null, null, 7, 'loser', 8, 'loser', '2026-11-12 17:00', 'Hunter F3'),
    (13, 'winners', null, null, 1, 'winner', 2, 'winner', '2026-11-12 18:00', 'Hunter F1'),
    (14, 'winners', null, null, 3, 'winner', 4, 'winner', '2026-11-12 18:00', 'Hunter F2'),
    (15, 'winners', null, null, 5, 'winner', 6, 'winner', '2026-11-12 18:00', 'Hunter F3'),
    (16, 'winners', null, null, 7, 'winner', 8, 'winner', '2026-11-12 19:00', 'Hunter F1'),
    (17, 'losers', null, null, 11, 'loser', 12, 'winner', '2026-11-13 09:00', 'Pioneer F3'),
    (18, 'losers', null, null, 12, 'loser', 11, 'winner', '2026-11-13 08:00', 'Pioneer F3'),
    (19, 'losers', null, null, 9, 'loser', 10, 'winner', '2026-11-13 08:00', 'Pioneer F2'),
    (20, 'losers', null, null, 10, 'loser', 9, 'winner', '2026-11-13 08:00', 'Pioneer F1'),
    (21, 'losers', null, null, 16, 'loser', 20, 'winner', '2026-11-13 09:00', 'Pioneer F1'),
    (22, 'losers', null, null, 15, 'loser', 19, 'winner', '2026-11-13 09:00', 'Pioneer F2'),
    (23, 'losers', null, null, 14, 'loser', 18, 'winner', '2026-11-13 10:00', 'Pioneer F2'),
    (24, 'losers', null, null, 13, 'loser', 17, 'winner', '2026-11-13 10:00', 'Pioneer F3'),
    (25, 'winners', null, null, 13, 'winner', 14, 'winner', '2026-11-13 10:00', 'Pioneer F1'),
    (26, 'winners', null, null, 15, 'winner', 16, 'winner', '2026-11-13 11:00', 'Pioneer F3'),
    (27, 'losers', null, null, 21, 'winner', 22, 'winner', '2026-11-13 11:00', 'Pioneer F1'),
    (28, 'losers', null, null, 23, 'winner', 24, 'winner', '2026-11-13 11:00', 'Pioneer F2'),
    (29, 'losers', null, null, 25, 'loser', 27, 'winner', '2026-11-13 12:00', 'Pioneer F1'),
    (30, 'losers', null, null, 26, 'loser', 28, 'winner', '2026-11-13 12:00', 'Pioneer F2'),
    (31, 'winners', null, null, 25, 'winner', 26, 'winner', '2026-11-13 12:00', 'Pioneer F3'),
    (32, 'losers', null, null, 29, 'winner', 30, 'winner', '2026-11-13 13:00', 'Pioneer F3'),
    (33, 'losers', null, null, 31, 'loser', 32, 'winner', '2026-11-13 14:00', 'Pioneer F3'),
    (34, 'final', null, null, 31, 'winner', 33, 'winner', '2026-11-13 15:00', 'Pioneer F3'),
    (35, 'final', null, null, 34, 'winner', 34, 'loser', '2026-11-13 16:00', 'Pioneer F3');

  -- A row whose side changed would collide on the unique key differently;
  -- clear pending rows of this division that sit on the wrong side.
  delete from public.games g using _sheet s
   where g.division_id = v_div and g.bracket_group = 'main' and g.round = s.n
     and g.bracket_side <> s.side and g.status = 'pending';

  insert into public.games (
    division_id, bracket_group, bracket_side, round, slot,
    team1_name, team2_name, field, scheduled_time, status
  )
  select v_div, 'main', s.side, s.n, 0, s.t1, s.t2, s.field,
         (s.at_local::timestamp at time zone v_tz), 'pending'
    from _sheet s
  on conflict (division_id, bracket_group, bracket_side, round, slot) do update
    set team1_name = excluded.team1_name,
        team2_name = excluded.team2_name,
        field = excluded.field,
        scheduled_time = excluded.scheduled_time,
        updated_at = now()
    where public.games.status = 'pending'
      and (public.games.team1_name, public.games.team2_name, public.games.field, public.games.scheduled_time)
          is distinct from (excluded.team1_name, excluded.team2_name, excluded.field, excluded.scheduled_time);

  -- 6. Winner/Loser links by sheet G#.
  update public.games g
     set team1_source_game_id = f1.id,
         team1_source_result = s.r1,
         team2_source_game_id = f2.id,
         team2_source_result = s.r2,
         updated_at = now()
    from _sheet s
    left join public.games f1 on f1.division_id = v_div and f1.bracket_group = 'main' and f1.round = s.s1
    left join public.games f2 on f2.division_id = v_div and f2.bracket_group = 'main' and f2.round = s.s2
   where g.division_id = v_div and g.bracket_group = 'main' and g.round = s.n
     and (g.team1_source_game_id, g.team1_source_result, g.team2_source_game_id, g.team2_source_result)
         is distinct from (f1.id, s.r1, f2.id, s.r2);

  select count(*) into v_n from public.games where division_id = v_div;
  if v_n <> 35 then raise exception 'expected 35 Men''s D games, found %', v_n; end if;
  select count(*) into v_n from public.games
   where division_id = v_div
     and ((team1_name is null and team1_source_game_id is null) or (team2_name is null and team2_source_game_id is null));
  if v_n <> 0 then raise exception '% Men''s D games have an unfed slot', v_n; end if;
  raise notice 'Men''s D loaded: division %, 35 games', v_div;
end $$;

